style.css:
@-moz-document domain("spotify.com") {
/* Kleuren */
:root {
  --my-cream: #f5ead8;
  --my-beige: #d9bd98;
  --my-tan: #b38a60;
  --my-brown: #70472d;
  --my-dark: #382317;
  --my-coffee: #24160f;
}

/* Achtergrond */
body,
.encore-dark-theme {
  background: var(--my-coffee) !important;
  color: var(--my-cream) !important;
}

/* Hoofdvenster */
[data-testid="main-view-container"] {
  background: linear-gradient(135deg, #382317, #59402e, #382317) !important;
}

/* Zijbalk */
[data-testid="sidebar"] {
  background: #302016 !important;
}

/* Bovenbalk */
[data-testid="topbar"] {
  background: #302016 !important;
}

/* Muziekspeler */
[data-testid="now-playing-bar"] {
  background: linear-gradient(90deg, #24160f, #795438, #24160f) !important;
}

/* Albumhoezen */
img {
  border-radius: 9px !important;
}

/* Albums */
[data-testid="card"] {
  background: rgba(217, 189, 152, 0.09) !important;
  border-radius: 14px !important;
}

/* Knoppen */
button {
  border-radius: 22px !important;
}

/* Teksten */
h1, h2, h3, p, span {
  color: var(--my-cream) !important;
}

/* Links */
a {
  color: var(--my-beige) !important;
}

/* Spotify kleuren */
:root {
  --background-base: #382317;
  --background-highlight: #59402e;
  --text-base: #f5ead8;
  --text-subdued: #d9bd98;
  --essential-base: #d9bd98;
}
}
